// two uint4 packed into one uint8, 
alignas(aie::vector_decl_align)  uint32 lut_u4_pair_2_MXFP4_bf16_ab[256 * 2] = {
    INSERT_TABLE
};
alignas(aie::vector_decl_align)  uint32 lut_u4_pair_2_MXFP4_bf16_cd[256 * 2] = {
    INSERT_TABLE
};

    // input 16 uint8, which represnt 32 values (4 bit per value in MXFP4)
    // dequant and store 32 bfloat16 data 
inline __attribute__((always_inline)) v32bfloat16 
mxfp4_to_bf16(v16uint8 vInput){

    aie::vector<uint8_t, 16> input = vInput;
    aie::vector<uint32_t, 16> output;

    using lut_type = aie::lut<4, uint32_t>;
    lut_type lut_i( 256,  lut_u4_pair_2_MXFP4_bf16_ab, lut_u4_pair_2_MXFP4_bf16_cd  );
    const uint32_t step_i = 0;

    aie::parallel_lookup<uint8_t, lut_type, aie::lut_oor_policy::truncate> lookup_i(lut_i, step_i);

    output= lookup_i.fetch(input.cast_to<uint8>());

    return output.cast_to<bfloat16>();
}


inline v16bfloat16
mxfp4_scalar_to_bf16(aie::vector<uint8_t, 16> &  x){

    aie::accum<acc32, 16> scalar_input;
    scalar_input.from_vector(x);
    
    
    aie::accum<acc32, 16> base = aie::add(scalar_input, 1);
    aie::accum<acc64, 16> bits_a = aie::mul(base.template to_vector<uint32_t>(), 0x00200000u);

    aie::vector<uint32_t, 16> bits_b = aie::upshift( aie::sub(scalar_input,1).template to_vector<uint32_t>(), 23);

    aie::mask<16> mask =  aie::ge<aie::vector<uint32_t, 16>, uint32_t>(
        
        scalar_input.template to_vector<uint32_t>(), 2);
    
    // // now, expand mask from bits to v16uint32
    aie::vector<uint32_t, 16> base_a_vec = bits_a.template to_vector<uint32_t>();
    aie::vector<uint32_t, 16> bits = aie::select(base_a_vec, bits_b, mask);

    aie::vector<uint32_t, 16> bits_shifted = aie::logical_downshift(bits, 16); // logic downshift on all elements


    aie::accum<acc32, 16> bits_shifted_accum;
    bits_shifted_accum.from_vector(bits_shifted);

    aie::vector<uint16_t, 16> res = bits_shifted_accum.template to_vector<uint16_t>();
    return res.cast_to<bfloat16>();
}



